style.css:
@-moz-document domain("youtube.com") {
/* Make video titles or general text green */
  ytd-video-renderer #video-title,
  ytd-rich-grid-media #video-title {
    color: #00FF00 !important; /* Bright Green */
  }

  /* Make specific buttons, badges, or alerts red */
  tp-yt-paper-button[aria-label*="Subscribe"] {
    background-color: #FF0000 !important; /* YouTube Red */
    color: #FFFFFF !important;
  }

  /* Example: Target comment text or specific elements with red */
  #content-text {
    color: #FF3333 !important; /* Soft Red */
  }
}
